import json, os, urllib.request
url=os.environ.get('GALAXY_URL','https://usegalaxy.org').rstrip('/')+'/api/tools'
key=os.environ.get('GALAXY_API_KEY') or os.environ.get('USEGALAXY_API_KEY')
payload={
 'history_id':'bbd44e69cb8906b52ef37c391f20aef1',
