 'inputs':{
   'operation_mode':{
     'command':'find_reference',
     'species':'Agrius convolvuli',
     'email':'',
     'organelle_type':'mitochondrion',
     'ncbi_api_key':'',
     'min_length':14000
   }
 }
}
req=urllib.request.Request(url, data=json.dumps(payload).encode(), headers={'x-api-key':key,'Content-Type':'application/json'})
try:
 with urllib.request.urlopen(req) as r:
  txt=r.read().decode(); print(txt)
  open('/workspace/run_trace/mitohifi_find_reference_api_response.json','w').write(txt)
except Exception as e:
